            kind: "database" | "role" | "membership" | "access" | "connect" | "writes";
            name: string;
            /** @description False where it was already there. Not an error: two people reading
             *     the same preconditions page both act on what it said.
             *
             *     `access` reports true whenever the grants were applied, which is
             *     every time: they are idempotent, and re-applying them is how a
             *     database provisioned before they existed is repaired.
             *      */
            created: boolean;
